PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "FP16 matrix multiplication (A * B^T)");
}
"""

_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void matmul_kernel(const half* __restrict__ A,
                              const half* __restrict__ B,
                              half* __restrict__ C,
                              int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;  // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x;  // N dimension

    if (row < M && col < N) {
        float sum = 0.0f;
        // accumulate in fp32 for better precision
        for (int k = 0; k < K; ++k) {
            half a = A[row * K + k];
            half b = B[col * K + k];   // B is stored as (N, K)
            sum += __half2float(a) * __half2float(b);
        }
        C[row * N + col] = __float2half(sum);
    }
}

void matmul_fp16(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(0);

    const dim3 block(16, 16);
    const dim3 grid((N + block.x - 1) / block.x,
                    (M + block.y - 1) / block.y);

    const half* A_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const half* B_ptr = reinterpret_cast<const half*>(B.data_ptr<at::Half>());
    half* C_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    // launch kernel
    matmul_kernel<<<grid, block>>>(A_ptr, B_ptr, C_ptr, M, N, K);
    // propagate any launch error
    AT_CUDA_CHECK(cudaGetLastError());
}
"""

# Compile the extension (the harness will supply the appropriate C++ standard flags)
_matmul_ext = load_inline(
    name="matmul_fp16_ext",
    cpp_sources=_cpp_source,
    cuda_sources=_cuda_source,
    functions=["matmul_fp16"],
    verbose=False,
)

