        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Computes C = A @ B.T for fp16 inputs using the custom kernel.

        Args:
            A: Tensor of shape (M, K), dtype torch.float16.
            B: Tensor of shape (N, K), dtype torch.float16.

